new=r'''void tst_QUrlInternal::decodeForLocalFile_data()
{
    QTest::addColumn<QString>("input");
    QTest::addColumn<QString>("expected");

    // empty expected means qt_urlRecode() should return 0 (nothing to decode)
    QTest::newRow("empty") << QString() << QString();
    QTest::newRow("no-percent") << u"/tmp/foo bar"_s << QString();
    QTest::newRow("literal-unicode") << u"/tmp/\u00e9t\u00e9"_s << QString();
    QTest::newRow("literal-nul") << u"/tmp/a\0b"_s << QString();

    QTest::newRow("space") << u"/tmp/foo%20bar"_s << u"/tmp/foo bar"_s;
    QTest::newRow("percent") << u"/tmp/100%25"_s << u"/tmp/100%"_s;
    QTest::newRow("double-percent") << u"25%2525"_s << u"25%25"_s;
    QTest::newRow("hash-question") << u"/tmp/a%23b%3Fc"_s << u"/tmp/a#b?c"_s;
    QTest::newRow("controls") << u"%0D%0A%1F%7F"_s << u"\r\n\x1f\x7f"_s;
    QTest::newRow("lowercase-hex") << u"%c3%a9"_s << u"\u00e9"_s;
    QTest::newRow("utf8-2") << u"/tmp/%C3%A9t%C3%A9"_s << u"/tmp/\u00e9t\u00e9"_s;
    QTest::newRow("utf8-3") << u"%E2%82%AC"_s << u"\u20ac"_s;
    QTest::newRow("utf8-4") << u"%F0%9F%98%80"_s << u"\U0001F600"_s;
    QTest::newRow("utf8-mixed-literal") << u"\u00e9%C3%A9"_s << u"\u00e9\u00e9"_s;
#ifndef Q_OS_WIN
    QTest::newRow("backslash") << u"a%5Cb"_s << u"a\\b"_s;
#endif

    // bad percent-encoding is left undecoded, like with QUrl::FullyDecoded
    QTest::newRow("bad-short") << u"a%2"_s << u"a%2"_s;
    QTest::newRow("bad-hex") << u"%2F%GG"_s << u"%2F%GG"_s;
}

void tst_QUrlInternal::decodeForLocalFile()
{
    QFETCH(QString, input);
    QFETCH(QString, expected);

    // prepend some data to be sure that it remains there
    const QString prefix = QTest::currentDataTag();
    QString output = prefix;

    qsizetype result = qt_urlRecode(output, input, QUrlDecodeForLocalFile);
    if (expected.isNull()) {
        QCOMPARE(result, 0);
        QCOMPARE(output, prefix);
        expected = input;
    } else {
        QCOMPARE(result, expected.size());
        QCOMPARE(output, prefix + expected);
    }

    // where there is nothing unsafe, the result matches QUrl::FullyDecoded
    // (which decodes non-ASCII only if the input was already pretty-decoded)
    QString pretty;
    if (!qt_urlRecode(pretty, input, QUrl::PrettyDecoded))
        pretty = input;
    QString fully;
    if (!qt_urlRecode(fully, pretty, QUrl::FullyDecoded))
        fully = pretty;
    QCOMPARE(fully, expected);
}

void tst_QUrlInternal::decodeForLocalFileRefused_data()
{
    QTest::addColumn<QString>("input");

    QTest::newRow("nul") << u"%00"_s;
    QTest::newRow("nul-middle") << u"/tmp/a%00b"_s;
    QTest::newRow("slash") << u"%2F"_s;
    QTest::newRow("slash-lowercase") << u"%2f"_s;
    QTest::newRow("slash-traversal") << u"/tmp/..%2F..%2Fetc%2Fpasswd"_s;
    QTest::newRow("slash-end") << u"/tmp/foo%20bar%2F"_s;
    QTest::newRow("slash-after-utf8") << u"%C3%A9%2F"_s;
    QTest::newRow("overlong-slash-2") << u"%C0%AF"_s;
    QTest::newRow("overlong-slash-3") << u"%E0%80%AF"_s;
    QTest::newRow("overlong-nul") << u"%C0%80"_s;
    QTest::newRow("latin1") << u"/tmp/%E9t%E9"_s;
    QTest::newRow("truncated-utf8") << u"/tmp/%C3"_s;
    QTest::newRow("truncated-utf8-literal") << u"%C3A9"_s;
    QTest::newRow("encoded-surrogate") << u"%ED%A0%80"_s;
#ifdef Q_OS_WIN
    QTest::newRow("backslash") << u"%5C"_s;
    QTest::newRow("backslash-lowercase") << u"..%5c..%5cWindows"_s;
    QTest::newRow("literal-backslash") << u"C:\\Windows"_s;
    QTest::newRow("literal-backslash-encoded") << u"C:\\%20"_s;
    QTest::newRow("literal-backslash-bad-encoding") << u"C:\\%G"_s;
#endif
}

void tst_QUrlInternal::decodeForLocalFileRefused()
{
    QFETCH(QString, input);

    const QString prefix = QTest::currentDataTag();
    QString output = prefix;
    QCOMPARE_LT(qt_urlRecode(output, input, QUrlDecodeForLocalFile), 0);
    QCOMPARE(output, prefix);
}

void tst_QUrlInternal::decodeForLocalFileInvalidUtf8_data()
{
    QTest::addColumn<QByteArray>("utf8");

    extern void loadInvalidUtf8Rows();
    loadInvalidUtf8Rows();

    QTest::newRow("utf8-mix-4") << QByteArray("\xE0.A2\x80");
    QTest::newRow("utf8-mix-5") << QByteArray("\xE0\xA2.80");
    QTest::newRow("utf8-mix-6") << QByteArray("\xE0\xA2\x33");
}

void tst_QUrlInternal::decodeForLocalFileInvalidUtf8()
{
    QFETCH(QByteArray, utf8);
    const QString input = QString::fromLatin1(utf8.toPercentEncoding());

    const QString prefix = QTest::currentDataTag();
    QString output = prefix;
    QCOMPARE_LT(qt_urlRecode(output, input, QUrlDecodeForLocalFile), 0);
    QCOMPARE(output, prefix);
}

void tst_QUrlInternal::decodeForLocalFileNonCharacters_data()
{
    QTest::addColumn<QByteArray>("utf8");
    QTest::addColumn<QString>("utf16");

    extern void loadNonCharactersRows();
    loadNonCharactersRows();
}

void tst_QUrlInternal::decodeForLocalFileNonCharacters()
{
    // non-characters are valid UTF-8, so they are decoded
    QFETCH(QByteArray, utf8);
    QFETCH(QString, utf16);
    const QString input = QString::fromLatin1(utf8.toPercentEncoding());

    const QString prefix = QTest::currentDataTag();
    QString output = prefix;
    QCOMPARE(qt_urlRecode(output, input, QUrlDecodeForLocalFile), utf16.size());
    QCOMPARE(output, prefix + utf16);
}

